// One item per storefront. Keep this list in sync with the reviews workflow.
const APP_ID = '1209815023';
const COUNTRIES = ['us', 'gb', 'ca', 'au', 'br', 'in'];

// One timestamp for the whole run, so a run's rows group together.
const snapshotAt = new Date().toISOString();

return COUNTRIES.map((country) => ({ json: { appId: APP_ID, country, snapshotAt } }));

// Apple serves this endpoint as text/javascript, so the HTTP node returns raw text
// and we parse it here.
const req = $('Countries').item.json;

let body;
try {
  body = JSON.parse($json.data);
} catch (e) {
  throw new Error(`iTunes lookup ${req.country}: response is not JSON`);
}

const app = (body.results || []).find((r) => String(r.trackId) === req.appId);
if (!app) {
  throw new Error(`iTunes lookup ${req.country}: app ${req.appId} missing (resultCount=${body.resultCount})`);
}

const text = (v) => (v === undefined || v === null ? '' : String(v));
const int = (v) => (Number.isInteger(v) ? v : '');

// Averages are written as text: the report derives the mean of NEW ratings from
// them, so every decimal Apple returns has to survive Sheets formatting.
return {
  json: {
    snapshot_at: req.snapshotAt,
    country: req.country.toUpperCase(),
    app_id: req.appId,
    app_version: text(app.version),
    current_version_release_date: text(app.currentVersionReleaseDate),
    user_rating_count: int(app.userRatingCount),
    average_user_rating: text(app.averageUserRating),
    user_rating_count_current_version: int(app.userRatingCountForCurrentVersion),
    average_user_rating_current_version: text(app.averageUserRatingForCurrentVersion),
  },
};
